import React, { useEffect, useState } from "react";
import { BrowserRouter, Link, NavLink, Navigate, Route, Routes, useLocation, useNavigate } from "react-router-dom";
import { ArrowRight, ArrowUpRight, BadgeCheck, BookOpen, BriefcaseBusiness, Check, ChevronDown, CircleHelp, Compass, FileCheck2, FileSearch, FileText, Globe2, GraduationCap, Layers3, LockKeyhole, LogIn, Menu, MessageCircle, Plane, Search, ShieldCheck, Sparkles, UserRound, WalletCards, X, Clock3, ClipboardList, ChartNoAxesCombined, Download, ExternalLink, LoaderCircle } from "lucide-react";
import { backend } from "@/lib/backend";

type Notice={kind:"success"|"error"|"info";text:string};
const AUTH_ENABLED=false; // Keep authentication disabled during interface inspection; enable only after approval.
const areas=[
 {icon:GraduationCap,title:"Career and Education",desc:"Career reports, education pathways, career change and opportunity research."},
 {icon:BriefcaseBusiness,title:"Business Information",desc:"Business profiles, market context, industry research and opportunity assessment."},
 {icon:FileText,title:"Contracts and Commitments",desc:"Information to help understand agreements, obligations and commitments."},
 {icon:Plane,title:"Travel and Relocation",desc:"Destination, relocation, travel requirements and planning information."},
 {icon:FileCheck2,title:"Info and Report Verification",desc:"Evidence-led review of documents, reports, claims and supplied information."},
];
const careerOptions=["Career Reports","Educational Pathway","Career Change","Career Opportunities","One-on-One Session","Other Career Requests"];
function Button({children,onClick,type="button",variant="primary",disabled=false}:{children:React.ReactNode;onClick?:()=>void;type?:"button"|"submit";variant?:"primary"|"secondary"|"ghost";disabled?:boolean}){
 return <button type={type} disabled={disabled} onClick={onClick} className={`btn btn-${variant}`}>{children}</button>;
}
function Brand(){return <Link to="/" className="brand"><span className="brand-mark"><Compass size={22}/></span><span><b>Info Solutions</b><small>by Amineva Global</small></span></Link>}
function Header({user,onLogout}:{user:any;onLogout:()=>void}){
 const [open,setOpen]=useState(false),[role,setRole]=useState<string|null>(null);
 useEffect(()=>{if(user?.id)backend.role(user.id).then(setRole).catch(()=>setRole(null));else setRole(null);},[user?.id]);
 return <header className="site-header"><div className="container header-inner"><Brand/><nav className={open?"nav nav-open":"nav"}><NavLink to="/discover" onClick={()=>setOpen(false)}>Info Discovery</NavLink><NavLink to="/infoservice" onClick={()=>setOpen(false)}>InfoService</NavLink><NavLink to="/how-it-works" onClick={()=>setOpen(false)}>How it works</NavLink></nav><div className="header-actions">{AUTH_ENABLED?(user?<><Link className="btn btn-ghost btn-small" to="/workspace">My workspace</Link>{(role==="admin"||role==="reviewer")&&<Link className="btn btn-ghost btn-small" to="/admin">Staff</Link>}<button className="avatar-btn" onClick={onLogout} title="Sign out"><UserRound size={17}/></button></>:<Link className="btn btn-secondary btn-small" to="/login">Sign in <ArrowUpRight size={15}/></Link>):<span className="preview-mode-pill">Preview</span>}<button className="mobile-toggle" onClick={()=>setOpen(!open)} aria-label="Toggle menu">{open?<X/>:<Menu/>}</button></div></div></header>
}
function Footer(){return <footer className="footer"><div className="container footer-grid"><div><Brand/><p className="footer-copy">Research, information discovery, analysis and professional information services for better-informed decisions.</p></div><div><b>Explore</b><Link to="/discover">Info Discovery</Link><Link to="/infoservice">InfoService</Link></div><div><b>Information</b><Link to="/how-it-works">How it works</Link><Link to="/about">About</Link><Link to="/contact">Contact</Link></div></div><div className="container footer-bottom"><span>© {new Date().getFullYear()} Amineva Global</span><span>Info Solutions</span></div></footer>}
function NoticeBar({notice,clear}:{notice:Notice|null;clear:()=>void}){if(!notice)return null;return <div className={`notice notice-${notice.kind}`} role="status">{notice.text}<button onClick={clear} aria-label="Dismiss"><X size={15}/></button></div>}
function Home(){return <><section className="hero"><div className="hero-orb orb-one"/><div className="hero-orb orb-two"/><div className="container hero-layout"><div className="hero-copy"><div className="eyebrow eyebrow-light"><span className="eyebrow-dot"/> INFORMATION SOLUTIONS BY AMINEVA GLOBAL</div><h1>Find the information.<br/><em>Understand what it means.</em></h1><p>Discover relevant information, assess evidence and get professional support for the questions and decisions that matter.</p><div className="hero-actions"><Link className="btn btn-accent" to="/discover">Start Info Discovery <ArrowRight size={17}/></Link><Link className="btn btn-outline-light" to="/infoservice">Explore InfoService</Link></div><div className="hero-note"><ShieldCheck size={16}/> Discover more. Understand better.</div></div><div className="hero-visual"><div className="visual-card visual-main"><div className="visual-top"><span className="visual-icon"><Compass size={18}/></span><span className="visual-label">INFO DISCOVERY</span><span className="live-dot"/></div><div className="visual-title">A clearer view<br/>starts with a question.</div><div className="visual-search"><Search size={17}/><span>What do you need to understand?</span></div><div className="visual-lines"><i/><i/><i/></div><div className="visual-footer"><span><BadgeCheck size={14}/> Evidence-led approach</span><span>01 / 03</span></div></div><div className="float-card float-a"><span className="float-symbol"><FileCheck2 size={17}/></span><span><b>Verification</b><small>Evidence reviewed</small></span><Check size={16} className="check-icon"/></div><div className="float-card float-b"><span className="float-symbol amber"><ChartNoAxesCombined size={17}/></span><span><b>Analysis</b><small>Context made useful</small></span></div><div className="visual-ring"/></div></div></section><section className="trust-strip"><div className="container trust-items"><span><Search/> Discover information</span><span><ShieldCheck/> Assess and verify</span><span><FileText/> Structured reports</span><span><MessageCircle/> Professional support</span></div></section><section className="section section-intro"><div className="container"><div className="section-heading"><div><div className="eyebrow">WHAT WE DO</div><h2>Two ways to get the<br/><em>information you need.</em></h2></div><p>Discover information yourself, or engage our team when you need a professional service.</p></div><div className="service-grid"><article className="service-card discovery-card"><div className="service-icon"><Compass size={25}/></div><div className="service-tag">SELF-SERVICE</div><h3>Info Discovery</h3><p>Explore a question, follow the evidence and turn complex information into something useful.</p><ul><li><Check/> Discover and analyze</li><li><Check/> Verify and connect</li><li><Check/> Export your finished outcome</li><li><Check/> Sensitive Info investigations</li></ul><Link className="text-link" to="/discover">Start discovering <ArrowRight size={16}/></Link><div className="card-watermark"><Compass size={130}/></div></article><article className="service-card infoservice-card"><div className="service-icon service-icon-amber"><Layers3 size={25}/></div><div className="service-tag tag-amber">PROFESSIONAL SERVICES</div><h3>InfoService</h3><p>For requests requiring consultation, deeper research, specialist review or direct engagement, work with us on a defined scope.</p><ul><li><Check/> Individual request assessment</li><li><Check/> Discussion and tailored quotation</li><li><Check/> Agreed professional delivery</li></ul><Link className="text-link text-link-amber" to="/infoservice">Discuss a service <ArrowRight size={16}/></Link><div className="card-watermark"><Layers3 size={130}/></div></article></div></div></section><section className="section areas-section"><div className="container"><div className="center-heading"><div className="eyebrow">AREAS OF SUPPORT</div><h2>Information across<br/><em>important areas.</em></h2><p>Our service areas reflect the different questions people and organisations need answered.</p></div><div className="area-grid">{areas.map(({icon:Icon,title,desc})=><div className="area-card" key={title}><span><Icon size={21}/></span><h3>{title}</h3><p>{desc}</p></div>)}</div></div></section><section className="cta-band"><div className="container cta-inner"><div><div className="eyebrow eyebrow-light">YOUR QUESTION IS A GOOD START</div><h2>What do you need<br/>to know?</h2><p>Start with your question. We will help define the information and next steps.</p></div><Link className="btn btn-accent" to="/discover">Start Info Discovery <ArrowRight size={17}/></Link></div></section></>}
function PageIntro({eyebrow,title,desc}:{eyebrow:string;title:string;desc:string}){return <div className="page-intro"><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{desc}</p></div>}
function Field({label,children,required=false,hint}:{label:string;children:React.ReactNode;required?:boolean;hint?:string}){return <label className="field"><span>{label}{required&&<b> *</b>}</span>{children}{hint&&<small>{hint}</small>}</label>}
function Discover({user,setNotice}:{user:any;setNotice:(n:Notice)=>void}) {
 const loc=useLocation();
 const [question,setQuestion]=useState("");
 const [discoveryMode,setDiscoveryMode]=useState<"general"|"sensitive">("general");
 const [busy,setBusy]=useState(false);
 const [result,setResult]=useState<any>(null);
 const [showFull,setShowFull]=useState(false); const [showPricing,setShowPricing]=useState(false);
 async function run(e:React.FormEvent){
  e.preventDefault();
  if(question.trim().length<2){setNotice({kind:"error",text:"Enter what you want to find out."});return;}
  if(!AUTH_ENABLED){setNotice({kind:"info",text:"Preview mode: AI discovery will activate when the backend is connected."});return;}
  if(!user){setNotice({kind:"info",text:"Sign in to start and save your discovery."});return;}
  setBusy(true);setResult(null);setShowFull(false);
  try{const data=await backend.discover({question:question.trim(),mode:discoveryMode});setResult({...data,discovery_mode:discoveryMode});setShowPricing(true);setNotice({kind:"success",text:"Your information overview is ready."});}
  catch(err:any){setNotice({kind:"error",text:err.message||"The discovery could not be completed. Please try again."});}
  finally{setBusy(false);}
 }
 async function unlock(){
  if(!result?.run_id){setNotice({kind:"error",text:"This report does not have a valid discovery reference."});return;}
  setBusy(true);
  try{const data=await backend.unlockDiscovery(result.run_id);if(data?.checkout_url)location.assign(data.checkout_url);else if(data?.report){setResult((r:any)=>({...r,report:data.report,full_access:true}));setShowFull(true);}else setNotice({kind:"info",text:data?.message||"Payment checkout is not configured yet."});}
  catch(e:any){setNotice({kind:"error",text:e.message||"Could not open report checkout."});}
  finally{setBusy(false);}
 }
 useEffect(()=>{
  const runId=new URLSearchParams(loc.search).get("run");
  if(!user||!runId)return;
  backend.table("discovery_runs",`select=*&id=eq.${runId}&user_id=eq.${user.id}&limit=1`).then(async(rows:any[])=>{
   const row=rows[0];if(!row)return;
   setQuestion(row.question||"");
   setDiscoveryMode(row.discovery_mode==="sensitive"?"sensitive":"general");
   setResult({run_id:row.id,title:row.title,preview:row.preview,recommendations:row.recommendations||[],price:row.price,currency:row.currency,payment_status:row.payment_status,pricing_tier:row.pricing_tier,discovery_mode:row.discovery_mode||"general"}); if(row.payment_status!=="paid")setShowPricing(true);
   if(row.payment_status==="paid"||new URLSearchParams(loc.search).get("payment")==="success"){
    const unlocked=await backend.unlockDiscovery(row.id);
    if(unlocked?.report)setResult((old:any)=>({...old,...unlocked}));
   }
  }).catch((e:any)=>setNotice({kind:"error",text:e.message||"Could not load this discovery."}));
 },[user?.id,loc.search]);
 const recommendations=(result?.recommendations||[]).filter((p:any)=>["AgroClimate","Adesua","Inventra","SikaSem","DataLens"].includes(p.name));
 return <div className="page-wrap"><div className="container">
  <PageIntro eyebrow="INFO DISCOVERY" title="A world of information. One search." desc="Discover what matters. See the connections. Get to the answer."/>
  <div className="discovery-mode-grid" role="group" aria-label="Discovery mode">
   <button type="button" className={discoveryMode==="general"?"discovery-mode-card active":"discovery-mode-card"} onClick={()=>setDiscoveryMode("general")}><span className="discovery-mode-icon"><Compass size={20}/></span><span><b>Info Discovery</b><small>Explore any question, topic or subject.</small></span></button>
   <button type="button" className={discoveryMode==="sensitive"?"discovery-mode-card sensitive active":"discovery-mode-card sensitive"} onClick={()=>setDiscoveryMode("sensitive")}><span className="discovery-mode-icon"><ShieldCheck size={20}/></span><span><b>Sensitive Info</b><small>Investigate difficult-to-find public-interest information.</small></span></button>
  </div>
  <div className="discovery-search-hero">
   <form className="panel discovery-search" onSubmit={run}>
    <label className="discovery-query-label" htmlFor="discovery-question">{discoveryMode==="sensitive"?"What would you like to investigate?":"What do you want to discover?"}</label>
    <textarea id="discovery-question" value={question} onChange={e=>setQuestion(e.target.value)} rows={3} maxLength={10000} placeholder={discoveryMode==="sensitive"?"Try: Explore a company’s public ownership, major contracts and regulatory history.":"Ask anything. Explore a topic. Find the information you need…"} autoFocus/>
    <div className="discovery-form-bottom"><span><ShieldCheck size={15}/> {discoveryMode==="sensitive"?"Public-interest research. Evidence-led findings.":"Discover · Analyze · Verify · Connect · Understand"}</span><Button type="submit" disabled={busy}>{busy?<><LoaderCircle className="spin"/> Exploring</>:<>Discover <ArrowRight size={16}/></>}</Button></div>
   </form>
  </div>
  {result&&showPricing&&!result.full_access&&<div className="modal-backdrop" role="dialog" aria-modal="true" aria-label="Report access"><div className="pricing-modal"><button className="modal-close" onClick={()=>setShowPricing(false)} aria-label="Close"><X/></button><div className="eyebrow">YOUR REPORT IS READY</div><h2>{result.pricing_tier||"Report"} access</h2><p>Your findings are prepared. Unlock the complete report to view, print or download it.</p><div className="modal-price">{result.currency||"USD"} {Number(result.price||0).toFixed(2)} <small>one-time payment</small></div><div className="modal-actions"><Button onClick={()=>{setShowPricing(false);unlock();}} disabled={busy}>Unlock report <ArrowRight size={16}/></Button><Button variant="ghost" onClick={()=>setShowPricing(false)}>Not now</Button></div></div></div>}
  {result&&<section className="discovery-results">
   <div className="results-heading"><div><div className="eyebrow">{result.discovery_mode==="sensitive"?"SENSITIVE INFO":"DISCOVERY RESULTS"}</div><h2>{result.title||"Information overview"}</h2><p>{result.preview?.summary||result.summary||""}</p></div><span className="review-badge"><FileCheck2 size={15}/> Overview ready</span></div>
   <div className="review-panel">
    <div className="review-label">OVERVIEW</div>
    <div className="finding-section"><p>{result.preview?.overview||result.preview?.content||result.preview?.sections?.map((s:any)=>s.content||s.text||"").filter(Boolean).join("\n\n")||"Your overview is ready. Unlock the full document to access the complete organized information."}</p></div>
    <div className="preview-lock"><div><LockKeyhole size={20}/><span><b>Complete information document</b><small>Access the full research, analysis, verification, organized findings and connected information.</small></span></div>{result.full_access||showFull?<Button variant="secondary" onClick={()=>window.print()}><Download size={16}/> Print / Save document</Button>:<Button onClick={unlock} disabled={busy}>{busy?<LoaderCircle className="spin"/>:null} Access full document{result.price!=null?` · ${result.currency||"USD"} ${Number(result.price).toFixed(2)}`:""} <ArrowRight size={16}/></Button>}</div>
    {result.full_access&&<div className="full-report">{result.report?.content||result.report?.body||result.report_content||""}</div>}
   </div>
   {recommendations.length>0&&<div className="product-recommendations"><div className="eyebrow">RELATED AMINEVA SERVICES</div><div className="recommendation-grid">{recommendations.map((p:any,i:number)=><article className="recommendation-card" key={p.name||i}><span className="service-icon"><Sparkles size={20}/></span><h4>{p.name}</h4><p>{p.reason||""}</p>{p.url&&<a className="text-link" href={p.url} target="_blank" rel="noreferrer">Explore {p.name} <ExternalLink size={15}/></a>}</article>)}</div></div>}
  </section>}
 </div></div>;
}

function InfoService({user,setNotice}:{user:any;setNotice:(n:Notice)=>void}) {
 const nav=useNavigate();const [category,setCategory]=useState("career_education");const [detail,setDetail]=useState("");const [name,setName]=useState("");const [email,setEmail]=useState(user?.email||"");const [submitting,setSubmitting]=useState(false);const [done,setDone]=useState(false);
 async function submit(e:React.FormEvent){e.preventDefault();if(AUTH_ENABLED&&!user){nav("/login?next=/infoservice");return;}if(detail.trim().length<20){setNotice({kind:"error",text:"Please describe your service request in more detail."});return;}if(!AUTH_ENABLED){setDone(true);setNotice({kind:"info",text:"Preview only: this request has not been sent. Submission activates when the backend is connected."});return;}setSubmitting(true);try{await backend.insert("infoservice_requests",{user_id:user.id,full_name:name.trim(),email:email.trim(),category,request_details:detail.trim(),status:"submitted"});setDone(true);setNotice({kind:"success",text:"Your InfoService request has been received for assessment."});}catch(err:any){setNotice({kind:"error",text:err.message||"Could not submit your request."});}finally{setSubmitting(false);}}
 return <div className="page-wrap"><div className="container"><PageIntro eyebrow="PROFESSIONAL INFORMATION SERVICES" title="InfoService" desc="Some requests need more than a self-service report. Tell us what you need and we will assess the engagement, discuss the scope and provide a quotation."/><div className="info-service-layout"><div className="service-area-list"><h2>Service areas</h2>{areas.map(({icon:Icon,title,desc},i)=><div className="service-area-row" key={title}><span><Icon size={20}/></span><div><h3>{title}</h3><p>{i===0?"Career Reports · Educational Pathway · Career Change · Career Opportunities · One-on-One Session · Other Career Requests":desc}</p></div></div>)}<div className="process-box"><b>How engagements proceed</b><p>Request → Assessment → Discussion → Quotation → Invoice → Payment → Service delivery.</p><small>Every engagement is priced according to its agreed scope.</small></div></div><form className="panel form-panel" onSubmit={submit}>{done?<div className="success-state"><span><Check size={28}/></span><h2>Request received</h2><p>Our team will assess your request and follow up on the scope and next steps.</p><Link className="btn btn-primary" to="/workspace">View workspace</Link></div>:<><div className="form-title"><h2>Tell us about your request</h2><p>Sign in to submit and track your service request.</p></div><Field label="Service area" required><select value={category} onChange={e=>setCategory(e.target.value)}>{areas.map((a,i)=><option value={["career_education","business_information","contracts_commitments","travel_relocation","info_report_verification"][i]} key={a.title}>{a.title}</option>)}</select></Field>{category==="career_education"&&<Field label="Career and education request type"><select value={detail.startsWith("Type:")?detail.split("\n")[0].slice(6):""} onChange={e=>setDetail("Type: "+e.target.value+"\n\n") }><option value="">Select a request type</option>{careerOptions.map(x=><option key={x}>{x}</option>)}</select></Field>}<Field label="Full name" required><input value={name} onChange={e=>setName(e.target.value)} required placeholder="Your name"/></Field><Field label="Email address" required><input type="email" value={email} onChange={e=>setEmail(e.target.value)} required placeholder="you@example.com"/></Field><Field label="Describe the support you need" required><textarea rows={6} minLength={20} maxLength={5000} value={detail} onChange={e=>setDetail(e.target.value)} placeholder="Explain your situation, what you need us to do and any important deadlines."/></Field><div className="form-foot"><span><LockKeyhole size={14}/> Private service request</span><Button type="submit" disabled={submitting}>{submitting?<><LoaderCircle className="spin"/> Submitting</>:<>Submit request <ArrowRight size={16}/></>}</Button></div></>}</form></div></div></div>
}
function AuthPage({mode,setUser,setNotice}:{mode:"login"|"signup";setUser:(u:any)=>void;setNotice:(n:Notice)=>void}){
 const nav=useNavigate(),loc=useLocation();const [email,setEmail]=useState(""),[password,setPassword]=useState(""),[name,setName]=useState(""),[loading,setLoading]=useState(false);const [show,setShow]=useState(false);
 async function submit(e:React.FormEvent){e.preventDefault();setLoading(true);try{if(mode==="signup"){const r=await backend.signUp(email,password,name);if(!r.access_token){setNotice({kind:"success",text:"Account created. Check your email to confirm your address, then sign in."});nav("/login");return;}setUser(r.user);}else{const r=await backend.signIn(email,password);setUser(r.user);}setNotice({kind:"success",text:mode==="signup"?"Your account is ready.":"You are signed in."});const next=new URLSearchParams(loc.search).get("next");nav(next&&next.startsWith("/")?next:"/workspace");}catch(err:any){setNotice({kind:"error",text:err.message||"Authentication failed."});}finally{setLoading(false);}}
 return <div className="auth-page"><div className="auth-card"><Brand/><div className="auth-heading"><div className="eyebrow">{mode==="login"?"WELCOME BACK":"CREATE YOUR ACCOUNT"}</div><h1>{mode==="login"?"Sign in to continue.":"Create your account."}</h1><p>{mode==="login"?"Access your requests, reports and service updates.":"One account to submit requests and manage your information services."}</p></div><form onSubmit={submit} className="auth-form">{mode==="signup"&&<Field label="Full name" required><input value={name} onChange={e=>setName(e.target.value)} required autoComplete="name" placeholder="Your full name"/></Field>}<Field label="Email address" required><input type="email" value={email} onChange={e=>setEmail(e.target.value)} required autoComplete="email" placeholder="you@example.com"/></Field><Field label="Password" required><div className="password-wrap"><input type={show?"text":"password"} value={password} onChange={e=>setPassword(e.target.value)} required minLength={8} autoComplete={mode==="login"?"current-password":"new-password"} placeholder="At least 8 characters"/><button type="button" onClick={()=>setShow(!show)}>{show?"Hide":"Show"}</button></div></Field><Button type="submit" disabled={loading}>{loading?<><LoaderCircle className="spin"/> Please wait</>:mode==="login"?"Sign in":"Create account"} <ArrowRight size={16}/></Button></form>{mode==="login"&&<p className="auth-switch"><Link to="/forgot-password">Forgot your password?</Link></p>}<p className="auth-switch">{mode==="login"?"New to Info Solutions?":"Already have an account?"} <Link to={mode==="login"?"/signup":"/login"}>{mode==="login"?"Create an account":"Sign in"}</Link></p><p className="auth-privacy"><LockKeyhole size={13}/> Your account information is protected.</p></div></div>
}
function ForgotPassword({setNotice}:{setNotice:(n:Notice)=>void}){const [email,setEmail]=useState("");const [loading,setLoading]=useState(false);const [sent,setSent]=useState(false);async function submit(e:React.FormEvent){e.preventDefault();setLoading(true);try{await backend.resetPassword(email);setSent(true);setNotice({kind:"success",text:"If an account exists for that email, a password reset link has been sent."});}catch(err:any){setNotice({kind:"error",text:err.message||"Could not request a password reset."});}finally{setLoading(false);}}return <div className="auth-page"><div className="auth-card"><Brand/><div className="auth-heading"><div className="eyebrow">ACCOUNT RECOVERY</div><h1>Reset your password.</h1><p>Enter the email address associated with your account.</p></div>{sent?<div className="success-state"><span><Check/></span><h2>Check your email</h2><p>Follow the secure link to choose a new password.</p><Link to="/login" className="btn btn-primary">Back to sign in</Link></div>:<form className="auth-form" onSubmit={submit}><Field label="Email address" required><input type="email" value={email} onChange={e=>setEmail(e.target.value)} required placeholder="you@example.com"/></Field><Button type="submit" disabled={loading}>{loading?<><LoaderCircle className="spin"/> Sending</>:"Send reset link"}</Button></form>}<p className="auth-switch"><Link to="/login">Return to sign in</Link></p></div></div>}
function ResetPassword({setUser,setNotice}:{setUser:(u:any)=>void;setNotice:(n:Notice)=>void}){const nav=useNavigate();const [password,setPassword]=useState(""),[confirm,setConfirm]=useState(""),[loading,setLoading]=useState(false);async function submit(e:React.FormEvent){e.preventDefault();if(password.length<8||password!==confirm){setNotice({kind:"error",text:"Use at least 8 characters and make sure both passwords match."});return;}setLoading(true);try{await backend.updatePassword(password);setUser(await backend.user());setNotice({kind:"success",text:"Your password has been updated."});nav("/workspace");}catch(err:any){setNotice({kind:"error",text:err.message||"Could not update your password."});}finally{setLoading(false);}}return <div className="auth-page"><div className="auth-card"><Brand/><div className="auth-heading"><div className="eyebrow">SECURE ACCOUNT UPDATE</div><h1>Choose a new password.</h1><p>Set a new password for your Info Solutions account.</p></div><form className="auth-form" onSubmit={submit}><Field label="New password" required><input type="password" minLength={8} value={password} onChange={e=>setPassword(e.target.value)} required/></Field><Field label="Confirm new password" required><input type="password" minLength={8} value={confirm} onChange={e=>setConfirm(e.target.value)} required/></Field><Button type="submit" disabled={loading}>{loading?<><LoaderCircle className="spin"/> Updating</>:"Update password"}</Button></form></div></div>}
function Workspace({user,setNotice}:{user:any;setNotice:(n:Notice)=>void}){
 const [discovery,setDiscovery]=useState<any[]>([]),[services,setServices]=useState<any[]>([]),[reports,setReports]=useState<any[]>([]),[invoices,setInvoices]=useState<any[]>([]),[loading,setLoading]=useState(true);
 async function load(){if(!user)return;setLoading(true);try{const q=`select=*&user_id=eq.${user.id}&order=created_at.desc`;const [d,s,r,i]=await Promise.all([backend.table("discovery_runs",q),backend.table("infoservice_requests",q),backend.table("reports",q),backend.table("invoices",q)]);setDiscovery(d);setServices(s);setReports(r);setInvoices(i);}catch(e:any){setNotice({kind:"error",text:e.message||"Could not load your workspace."});}finally{setLoading(false);}}
 useEffect(()=>{load();},[user?.id]);
 return <div className="page-wrap"><div className="container"><div className="workspace-head"><div><div className="eyebrow">YOUR ACCOUNT</div><h1>My workspace</h1><p>Welcome back{user?.user_metadata?.full_name?", "+user.user_metadata.full_name:""}. Track requests, review invoices and access released reports.</p></div><Link className="btn btn-primary" to="/discover">New request <ArrowRight size={16}/></Link></div><div className="stats-grid"><div className="stat-card"><span>Info discoveries</span><b>{discovery.length}</b><small>Submitted by you</small></div><div className="stat-card"><span>InfoService requests</span><b>{services.length}</b><small>Professional engagements</small></div><div className="stat-card"><span>Reports available</span><b>{reports.filter(r=>r.status==="released").length}</b><small>Ready to access</small></div></div>{loading?<div className="loading"><LoaderCircle className="spin"/> Loading your workspace…</div>:<><div className="workspace-section"><div className="section-row"><h2>Info Discovery</h2><Link to="/discover">Start a discovery <ArrowRight size={14}/></Link></div><DiscoveryRunTable items={discovery}/></div><div className="workspace-section"><div className="section-row"><h2>InfoService</h2><Link to="/infoservice">New service request <ArrowRight size={14}/></Link></div><RequestTable items={services} kind="service"/></div><div className="workspace-section"><div className="section-row"><h2>Invoices and payments</h2></div><InvoiceList invoices={invoices}/></div><div className="workspace-section"><div className="section-row"><h2>My reports</h2><Link to="/reports">View all <ArrowRight size={14}/></Link></div><ReportList reports={reports}/></div></>}</div></div>
}
function Status({value}:{value:string}){const v=(value||"submitted").toLowerCase().replaceAll("_"," ");return <span className={`status status-${v.replaceAll(" ","-")}`}>{v}</span>}
function RequestTable({items,kind}:{items:any[];kind:string}){if(!items.length)return <div className="empty-state"><FileSearch size={22}/><p>No {kind==="discovery"?"discovery":"InfoService"} requests yet.</p></div>;return <div className="table-wrap"><table><thead><tr><th>Request</th><th>Submitted</th><th>Status</th></tr></thead><tbody>{items.map(x=><tr key={x.id}><td><b>{kind==="discovery"?(x.question||"Information request").slice(0,90):x.category?.replaceAll("_"," ")}</b><small>{kind==="discovery"?x.category?.replaceAll("_"," "):x.request_details?.slice(0,100)}</small>{kind==="discovery"&&x.preview_text&&<small className="customer-preview">Preview: {x.preview_text}</small>}</td><td>{x.created_at?new Date(x.created_at).toLocaleDateString():"—"}</td><td><Status value={x.status}/></td></tr>)}</tbody></table></div>}
function DiscoveryRunTable({items}:{items:any[]}){if(!items.length)return <div className="empty-state"><Compass size={22}/><p>Your completed information discoveries will appear here.</p></div>;return <div className="report-list">{items.map(x=><article className="report-card report-card-full" key={x.id}><div className="report-card-head"><Compass/><div><b>{x.title||x.question||"Information discovery"}</b><small>{x.created_at?new Date(x.created_at).toLocaleDateString():""} · {x.payment_status==="paid"?"Full report unlocked":"Review available"}</small></div></div><p>{x.preview?.summary||"Your discovery review is ready."}</p><div className="section-row"><span className="status">{x.currency||"GHS"} {x.price==null?"Price shown at unlock":Number(x.price).toFixed(2)}</span><Link className="text-link" to={`/discover?run=${x.id}`}>Open discovery <ArrowRight size={14}/></Link></div></article>)}</div>}
function InvoiceList({invoices}:{invoices:any[]}){if(!invoices.length)return <div className="empty-state"><WalletCards size={22}/><p>Invoices will appear here when a quotation is approved and issued.</p></div>;return <div className="table-wrap"><table><thead><tr><th>Invoice</th><th>Amount</th><th>Status</th><th>Issued</th></tr></thead><tbody>{invoices.map(x=><tr key={x.id}><td><b>{x.invoice_number}</b><small>{x.description}</small></td><td><b>{x.currency} {Number(x.amount).toFixed(2)}</b></td><td><Status value={x.status}/></td><td>{x.created_at?new Date(x.created_at).toLocaleDateString():"—"}</td></tr>)}</tbody></table></div>}
function ReportList({reports}:{reports:any[]}){const ready=reports.filter(r=>r.status==="released");if(!ready.length)return <div className="empty-state"><FileText size={22}/><p>Your completed reports will appear here when they are released.</p></div>;return <div className="report-list">{ready.map(r=><article className="report-card report-card-full" key={r.id}><div className="report-card-head"><FileText/><div><b>{r.title||"Information report"}</b><small>{r.created_at?new Date(r.created_at).toLocaleDateString():""}{r.verification_status?" · "+r.verification_status.replaceAll("_"," "):""}</small></div></div>{r.summary&&<p>{r.summary}</p>}{r.methodology&&<p><b>Methodology:</b> {r.methodology}</p>}{r.limitations&&<p><b>Limitations:</b> {r.limitations}</p>}{r.report_content?.body&&<details><summary>Read report</summary><div className="report-body">{r.report_content.body}</div></details>}{r.storage_path?<span className="report-file-note">A document file is attached to this report.</span>:null}</article>)}</div>}
function Reports({user,setNotice}:{user:any;setNotice:(n:Notice)=>void}){const [reports,setReports]=useState<any[]>([]);useEffect(()=>{if(user)backend.table("reports",`select=*&user_id=eq.${user.id}&status=eq.released&order=created_at.desc`).then(setReports).catch(e=>setNotice({kind:"error",text:e.message}));},[user?.id]);return <div className="page-wrap"><div className="container"><PageIntro eyebrow="YOUR DELIVERABLES" title="My reports" desc="Access the reports and deliverables that have been completed and released to your account."/><ReportList reports={reports}/></div></div>}
function Admin({user,setNotice}:{user:any;setNotice:(n:Notice)=>void}){
 const [role,setRole]=useState<string|null>(null),[loading,setLoading]=useState(true),[items,setItems]=useState<any[]>([]),[invoices,setInvoices]=useState<any[]>([]),[kind,setKind]=useState("all"),[selected,setSelected]=useState<any>(null),[status,setStatus]=useState("under_review"),[price,setPrice]=useState(""),[notes,setNotes]=useState(""),[previewText,setPreviewText]=useState(""),[invoiceDescription,setInvoiceDescription]=useState("Information research and report preparation"),[reportTitle,setReportTitle]=useState(""),[reportSummary,setReportSummary]=useState(""),[reportBody,setReportBody]=useState(""),[methodology,setMethodology]=useState(""),[limitations,setLimitations]=useState(""),[verification,setVerification]=useState("unverified"),[reportStatus,setReportStatus]=useState("review"),[busy,setBusy]=useState(false);
 async function load(){setLoading(true);try{const r=await backend.role(user.id);setRole(r);if(r==="admin"||r==="reviewer"){const [s,i]=await Promise.all([backend.table("infoservice_requests","select=*&order=created_at.desc&limit=100"),backend.table("invoices","select=*&order=created_at.desc&limit=100")]);setItems(s.map(x=>({...x,_kind:"service"})).sort((a,b)=>new Date(b.created_at).getTime()-new Date(a.created_at).getTime()));setInvoices(i);}}catch(e:any){setNotice({kind:"error",text:e.message});}finally{setLoading(false);}}
 useEffect(()=>{load();},[user?.id]);
 const relatedInvoice=selected?invoices.find(i=>selected._kind==="discovery"?i.discovery_request_id===selected.id:i.infoservice_request_id===selected.id):null;
 async function save(){if(!selected)return;setBusy(true);try{const table=selected._kind==="discovery"?"info_discovery_requests":"infoservice_requests";const values:any={status,assessment_notes:notes||null,reviewed_by:user.id,reviewed_at:new Date().toISOString()};if(selected._kind==="discovery")values.preview_text=previewText||null;if(price.trim())values.quoted_amount=Number(price);await backend.update(table,`id=eq.${selected.id}`,values);setNotice({kind:"success",text:"Request assessment saved."});await load();}catch(e:any){setNotice({kind:"error",text:e.message});}finally{setBusy(false);}}
 async function issueInvoice(){if(relatedInvoice){setNotice({kind:"error",text:"An invoice already exists for this request. Use the existing invoice record."});return;}if(!selected||!price||Number(price)<=0){setNotice({kind:"error",text:"Enter a quotation amount greater than zero first."});return;}setBusy(true);try{const row:any={user_id:selected.user_id,invoice_number:"AGIS-"+new Date().toISOString().slice(0,10).replaceAll("-","")+"-"+Math.random().toString(36).slice(2,7).toUpperCase(),description:invoiceDescription,amount:Number(price),currency:"USD",status:"issued",created_by:user.id};if(selected._kind==="discovery")row.discovery_request_id=selected.id;else row.infoservice_request_id=selected.id;const [created]=await backend.insert("invoices",row);await backend.update(selected._kind==="discovery"?"info_discovery_requests":"infoservice_requests",`id=eq.${selected.id}`,{status:"awaiting_payment",quoted_amount:Number(price)});setInvoices(prev=>[created,...prev]);setSelected({...selected,status:"awaiting_payment"});setStatus("awaiting_payment");setNotice({kind:"success",text:"Invoice issued and added to the customer's workspace."});}catch(e:any){setNotice({kind:"error",text:e.message});}finally{setBusy(false);}}
 async function confirmManualPayment(){if(!relatedInvoice){setNotice({kind:"error",text:"Issue an invoice before confirming payment."});return;}setBusy(true);try{await backend.rpc("confirm_manual_invoice_payment",{p_invoice_id:relatedInvoice.id,p_provider_reference:"MANUAL-"+relatedInvoice.id});setNotice({kind:"success",text:"Manual payment recorded. You can now prepare and release the report."});await load();}catch(e:any){setNotice({kind:"error",text:e.message});}finally{setBusy(false);}}
 async function createReport(){if(!selected||!reportTitle.trim()||!reportBody.trim()){setNotice({kind:"error",text:"Add a report title and report content first."});return;}if(reportStatus==="released"&&relatedInvoice&&relatedInvoice.status!=="paid"){setNotice({kind:"error",text:"This request has an unpaid invoice. Confirm payment before releasing its report."});return;}setBusy(true);try{const row:any={user_id:selected.user_id,title:reportTitle.trim(),summary:reportSummary.trim()||null,report_content:{body:reportBody},status:reportStatus,verification_status:verification,methodology:methodology||null,limitations:limitations||null,created_by:user.id,released_at:reportStatus==="released"?new Date().toISOString():null};if(selected._kind==="discovery")row.discovery_request_id=selected.id;else row.infoservice_request_id=selected.id;if(relatedInvoice)row.invoice_id=relatedInvoice.id;await backend.insert("reports",row);if(reportStatus==="released"){await backend.update(selected._kind==="discovery"?"info_discovery_requests":"infoservice_requests",`id=eq.${selected.id}`,{status:"released"});}setNotice({kind:"success",text:reportStatus==="released"?"Report released to the customer's workspace.":"Report draft saved for review."});setReportTitle("");setReportSummary("");setReportBody("");setMethodology("");setLimitations("");await load();}catch(e:any){setNotice({kind:"error",text:e.message});}finally{setBusy(false);}}
 if(loading)return <div className="loading"><LoaderCircle className="spin"/> Checking access…</div>;
 if(role!=="admin"&&role!=="reviewer")return <div className="page-wrap"><div className="container"><div className="empty-state large"><LockKeyhole size={30}/><h2>Admin access required</h2><p>This area is restricted to authorized Info Solutions staff.</p><Link to="/workspace" className="btn btn-secondary">Return to workspace</Link></div></div></div>;
 return <div className="page-wrap"><div className="container"><div className="workspace-head"><div><div className="eyebrow">OPERATIONS</div><h1>Request and report management</h1><p>Manage professional service requests, appointments, quotations, payments and agreed deliverables.</p></div><Button variant="secondary" onClick={load}>Refresh</Button></div><div className="admin-layout"><div className="admin-list"><div className="section-row"><h2>InfoService requests ({items.length})</h2><select value={kind} onChange={e=>setKind(e.target.value)}><option value="all">All InfoService engagements</option><option value="service">InfoService</option></select></div>{items.filter(x=>kind==="all"||x._kind===kind).map(x=><button className={selected?.id===x.id?"admin-item active":"admin-item"} key={x.id} onClick={()=>{setSelected(x);setStatus(x.status||"submitted");setPrice(x.quoted_amount||"");setNotes(x.assessment_notes||"");setPreviewText(x.preview_text||"");setReportTitle("");setReportSummary("");setReportBody("");setMethodology("");setLimitations("");}}><span className="admin-item-top"><b>{x._kind==="discovery"?"Info Discovery":"InfoService"}</b><Status value={x.status}/></span><strong>{(x.question||x.category||"Request").slice(0,80)}</strong><small>{x.created_at?new Date(x.created_at).toLocaleString():""}</small></button>)}</div><div className="panel admin-detail">{selected?<><div className="eyebrow">{selected._kind==="discovery"?"INFO DISCOVERY REQUEST":"INFOSERVICE REQUEST"}</div><h2>{selected.question||selected.category?.replaceAll("_"," ")}</h2><p className="admin-detail-copy">{selected.question||selected.request_details}</p>{selected.context&&<div className="note-box"><b>Context</b><p>{selected.context}</p></div>}<Field label="Request status"><select value={status} onChange={e=>setStatus(e.target.value)}>{["submitted","under_review","awaiting_customer","quoted","approved","in_progress","awaiting_payment","paid","completed","released","declined","cancelled"].map(s=><option key={s} value={s}>{s.replaceAll("_"," ")}</option>)}</select></Field><Field label="Quoted amount (GHS)"><input type="number" min="0" step="0.01" value={price} onChange={e=>setPrice(e.target.value)} placeholder="0.00"/></Field><Field label="Internal assessment notes"><textarea rows={4} value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Scope, evidence needed and next steps."/></Field>{selected._kind==="discovery"&&<Field label="Customer preview / proposed scope"><textarea rows={3} value={previewText} onChange={e=>setPreviewText(e.target.value)} placeholder="Summarise the proposed deliverable and what the customer can review before proceeding."/></Field>}<div className="admin-actions"><Button onClick={save} disabled={busy}>Save assessment <Check size={15}/></Button><Field label="Invoice description"><input value={invoiceDescription} onChange={e=>setInvoiceDescription(e.target.value)}/></Field><Button variant="secondary" onClick={issueInvoice} disabled={busy||!price||!!relatedInvoice}>Issue invoice <WalletCards size={15}/></Button></div>{relatedInvoice&&<div className="invoice-admin-box"><b>Invoice {relatedInvoice.invoice_number}</b><span>{relatedInvoice.currency} {Number(relatedInvoice.amount).toFixed(2)} · <Status value={relatedInvoice.status}/></span>{relatedInvoice.status!=="paid"&&<Button variant="secondary" onClick={confirmManualPayment} disabled={busy}>Record manual payment <Check size={15}/></Button>}</div>}<div className="report-editor"><div className="eyebrow">DELIVERABLE</div><h3>Prepare customer report</h3><Field label="Report title"><input value={reportTitle} onChange={e=>setReportTitle(e.target.value)} placeholder="Title of the report"/></Field><Field label="Executive summary"><textarea rows={3} value={reportSummary} onChange={e=>setReportSummary(e.target.value)} placeholder="A concise summary of findings."/></Field><Field label="Report content"><textarea rows={8} value={reportBody} onChange={e=>setReportBody(e.target.value)} placeholder="Write the report, findings, evidence, analysis and recommendations."/></Field><Field label="Methodology"><textarea rows={3} value={methodology} onChange={e=>setMethodology(e.target.value)} placeholder="Describe the research and assessment approach."/></Field><Field label="Limitations and outstanding checks"><textarea rows={3} value={limitations} onChange={e=>setLimitations(e.target.value)} placeholder="State any limits, gaps or matters needing further confirmation."/></Field><Field label="Verification assessment"><select value={verification} onChange={e=>setVerification(e.target.value)}>{["confirmed","contradicted","unverified","inconclusive","requires_further_confirmation"].map(x=><option value={x} key={x}>{x.replaceAll("_"," ")}</option>)}</select></Field><Field label="Save as"><select value={reportStatus} onChange={e=>setReportStatus(e.target.value)}><option value="draft">Draft</option><option value="review">Ready for review</option><option value="released">Release to customer</option></select></Field><Button onClick={createReport} disabled={busy}>Save report <FileText size={15}/></Button><p className="form-hint">Reports marked for release become visible in the customer's workspace. An issued invoice must be paid before its report can be released.</p></div></>:<div className="empty-state"><ClipboardList size={26}/><h3>Select a request</h3><p>Choose a submitted request to assess, quote and prepare its deliverable.</p></div>}</div></div></div></div>
}

function HowItWorks(){return <div className="page-wrap"><div className="container"><PageIntro eyebrow="A CLEAR PROCESS" title="From question to useful information." desc="Info Discovery turns a question into a structured review. InfoService provides a separate route for professional engagements."/><div className="how-grid">{[{n:"01",t:"Tell us what you need",d:"Enter a question in Info Discovery, or submit a separate InfoService engagement request."},{n:"02",t:"Assessment and scope",d:"The request is reviewed to determine the information required, evidence available and appropriate deliverable."},{n:"03",t:"Review the proposal",d:"For Info Discovery, review the findings and unlock the complete report when you choose. InfoService engagements receive an individual scope and quotation."},{n:"04",t:"Payment and delivery",d:"After payment, the full discovery report is unlocked. InfoService work proceeds according to the agreed engagement."}].map(x=><div className="how-card" key={x.n}><b>{x.n}</b><h3>{x.t}</h3><p>{x.d}</p></div>)}</div><div className="note-box"><ShieldCheck/><p>Verification findings are described according to available evidence. A result may be confirmed, contradicted, unverified, inconclusive or require further confirmation.</p></div></div></div>}
function About(){return <div className="page-wrap"><div className="container narrow"><PageIntro eyebrow="ABOUT THE PLATFORM" title="Information, made useful." desc="Info Solutions is a service platform by Amineva Global, built to help individuals and organisations discover, assess, verify and use relevant information."/><div className="prose"><h2>Our approach</h2><p>We start with the question that needs answering. We identify the relevant information, consider its context and reliability, organize the findings and make clear what the evidence supports.</p><p>Where a request requires additional expertise or direct engagement, InfoService provides a route to a tailored professional service.</p><h2>Clarity and evidence</h2><p>We distinguish between established facts, supported findings, claims that are contradicted, and matters that remain uncertain. We do not present an unverified claim as a confirmed fact.</p></div></div></div>}
function Contact(){return <div className="page-wrap"><div className="container narrow"><PageIntro eyebrow="GET IN TOUCH" title="Talk to our team." desc="For general enquiries about Info Solutions, partnerships or support, contact the Amineva Global team."/><div className="panel contact-panel"><div className="service-icon"><MessageCircle/></div><h2>How can we help?</h2><p>For self-service research and information discovery, use Info Discovery. For a tailored professional engagement, use InfoService.</p><div className="contact-links"><Link className="btn btn-primary" to="/discover">Info Discovery <ArrowRight size={16}/></Link><Link className="btn btn-secondary" to="/infoservice">InfoService <ArrowRight size={16}/></Link></div></div></div></div>}
function RequireUser({user,children}:{user:any;children:React.ReactNode}){const loc=useLocation();if(!user)return <Navigate to={`/login?next=${encodeURIComponent(loc.pathname+loc.search)}`} replace/>;return <>{children}</>}
function AuthModal({setUser,setNotice}:{setUser:(u:any)=>void;setNotice:(n:Notice)=>void}){const [mode,setMode]=useState<"login"|"signup">("login"),[email,setEmail]=useState(""),[password,setPassword]=useState(""),[name,setName]=useState(""),[busy,setBusy]=useState(false);const loc=useLocation(),nav=useNavigate();async function submit(e:React.FormEvent){e.preventDefault();setBusy(true);try{const r=mode==="signup"?await backend.signUp(email,password,name):await backend.signIn(email,password);if(!r.access_token){setNotice({kind:"success",text:"Account created. Check your email to confirm, then sign in."});setMode("login");return;}setUser(r.user);setNotice({kind:"success",text:"You are signed in."});nav(loc.pathname+loc.search,{replace:true});}catch(err:any){setNotice({kind:"error",text:err.message||"Authentication failed."});}finally{setBusy(false);}}return <div className="modal-backdrop auth-backdrop" role="dialog" aria-modal="true"><div className="auth-modal"><div className="auth-modal-head"><Brand/><span className="eyebrow">ONE ACCOUNT · TWO SERVICES</span><h2>{mode==="login"?"Welcome back":"Create your account"}</h2><p>Sign in or register to continue to Info Discovery and InfoService.</p></div><form className="auth-form" onSubmit={submit}>{mode==="signup"&&<Field label="Full name" required><input value={name} onChange={e=>setName(e.target.value)} required autoComplete="name"/></Field>}<Field label="Email address" required><input type="email" value={email} onChange={e=>setEmail(e.target.value)} required autoComplete="email"/></Field><Field label="Password" required><input type="password" value={password} onChange={e=>setPassword(e.target.value)} minLength={8} required autoComplete={mode==="login"?"current-password":"new-password"}/></Field><Button type="submit" disabled={busy}>{busy?<LoaderCircle className="spin"/>:mode==="login"?"Sign in":"Create account"}</Button></form><div className="social-auth"><button type="button" onClick={()=>backend.oauth("google")}>Continue with Google</button><button type="button" onClick={()=>backend.oauth("facebook")}>Continue with Facebook</button></div><p className="auth-switch">{mode==="login"?"New here?":"Already registered?"} <button type="button" onClick={()=>setMode(mode==="login"?"signup":"login")}>{mode==="login"?"Create account":"Sign in"}</button></p></div></div>}
function AccessGate({user,children,setUser,setNotice}:{user:any;children:React.ReactNode;setUser:(u:any)=>void;setNotice:(n:Notice)=>void}){return !AUTH_ENABLED||user?<>{children}</>:<AuthModal setUser={setUser} setNotice={setNotice}/>}
function AppShell(){const [user,setUser]=useState<any>(null),[notice,setNotice]=useState<Notice|null>(null),[boot,setBoot]=useState(true);useEffect(()=>{if(!AUTH_ENABLED){setBoot(false);return;}backend.user().then(setUser).catch(()=>setUser(null)).finally(()=>setBoot(false));},[]);async function logout(){try{await backend.signOut();}catch{}setUser(null);setNotice({kind:"success",text:"You have signed out."});}const set=(n:Notice)=>{setNotice(n);window.scrollTo({top:0,behavior:"smooth"});};if(boot)return <div className="boot-screen"><div className="brand-mark"><Compass/></div><span>Info Solutions</span></div>;return <><Header user={user} onLogout={logout}/><NoticeBar notice={notice} clear={()=>setNotice(null)}/><Routes><Route path="/" element={<Home/>}/><Route path="/discover" element={<AccessGate user={user} setUser={setUser} setNotice={set}><Discover user={user} setNotice={set}/></AccessGate>}/><Route path="/infoservice" element={<AccessGate user={user} setUser={setUser} setNotice={set}><InfoService user={user} setNotice={set}/></AccessGate>}/><Route path="/login" element={<AuthPage mode="login" setUser={setUser} setNotice={set}/>}/><Route path="/signup" element={<AuthPage mode="signup" setUser={setUser} setNotice={set}/>}/><Route path="/forgot-password" element={<ForgotPassword setNotice={set}/>}/><Route path="/reset-password" element={<ResetPassword setUser={setUser} setNotice={set}/>}/><Route path="/workspace" element={<RequireUser user={user}><Workspace user={user} setNotice={set}/></RequireUser>}/><Route path="/reports" element={<RequireUser user={user}><Reports user={user} setNotice={set}/></RequireUser>}/><Route path="/admin" element={<RequireUser user={user}><Admin user={user} setNotice={set}/></RequireUser>}/><Route path="/how-it-works" element={<HowItWorks/>}/><Route path="/about" element={<About/>}/><Route path="/contact" element={<Contact/>}/><Route path="*" element={<div className="page-wrap"><div className="container"><div className="empty-state large"><h2>Page not found</h2><Link to="/" className="btn btn-primary">Return home</Link></div></div></div>}/></Routes><Footer/></>}
export default function App(){return <BrowserRouter><AppShell/></BrowserRouter>}
